#!/usr/bin/env python """ Evaluate the trained XGBoost recommender model. This script loads the trained model and feature matrix, evaluates performance on a held-out test set, and generates sample recommendations. """ import pandas as pd import numpy as np import os import xgboost as xgb from sklearn.model_selection import train_test_split from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score # Paths FEATURE_MATRIX_PATH = 'vector_store/recipe_features.csv' MODEL_PATH = 'vector_store/xgboost_relevance_model.json' MAX_ROWS = 200000 def load_model(): """Load the trained XGBoost model.""" if not os.path.exists(MODEL_PATH): raise FileNotFoundError(f"Model not found at {MODEL_PATH}") model = xgb.Booster() model.load_model(MODEL_PATH) return model def load_features(): """Load the feature matrix with chunked reading and subsampling.""" if not os.path.exists(FEATURE_MATRIX_PATH): raise FileNotFoundError(f"Feature matrix not found at {FEATURE_MATRIX_PATH}") chunks = [] chunk_size = 50000 max_rows = MAX_ROWS for chunk in pd.read_csv(FEATURE_MATRIX_PATH, low_memory=False, on_bad_lines='skip', chunksize=chunk_size): numeric_cols = chunk.select_dtypes(include=['float64']).columns chunk = chunk.astype({col: 'float32' for col in numeric_cols}) chunks.append(chunk) if len(chunks) * chunk_size >= max_rows: break df = pd.concat(chunks, ignore_index=True) df.columns = df.columns.str.strip() possible_targets = [col for col in df.columns if 'rating' in col.lower()] if possible_targets: target_col = possible_targets[0] elif 'AggregatedRating' in df.columns: target_col = 'AggregatedRating' else: raise KeyError("Target column (AggregatedRating) not found in feature matrix.") return df, target_col def evaluate_model(model, X_test, y_test): """Evaluate the model and return metrics.""" dtest = xgb.DMatrix(X_test, label=y_test) y_pred = model.predict(dtest) mae = mean_absolute_error(y_test, y_pred) rmse = np.sqrt(mean_squared_error(y_test, y_pred)) r2 = r2_score(y_test, y_pred) return mae, rmse, r2, y_pred def generate_sample_recommendations(model, X_test, recipe_ids, n=3): """Generate sample recommendations for a few test recipes.""" dtest = xgb.DMatrix(X_test) y_pred = model.predict(dtest) results = [] for i in range(min(n, len(X_test))): similar_indices = np.argsort(np.abs(y_pred - y_pred[i]))[1:4] recs = [(recipe_ids[idx], y_pred[idx]) for idx in similar_indices] results.append({ 'base_recipe_id': recipe_ids[i], 'predicted_rating': y_pred[i], 'similar_recipes': recs }) return results def main(): print("[INFO] Loading model and features...") model = load_model() df, target_col = load_features() print(f"[INFO] Loaded {len(df)} recipes with {len(df.columns)} columns.") # Prepare features and target target = df[target_col].astype(np.float32) features = df.drop(columns=[target_col]).astype(np.float32) recipe_ids = df['RecipeId'].values # Split data X_train, X_test, y_train, y_test, ids_train, ids_test = train_test_split( features, target, recipe_ids, test_size=0.2, random_state=42 ) print(f"[INFO] Test set size: {len(X_test)} samples") # Evaluate print("[INFO] Evaluating model...") mae, rmse, r2, y_pred = evaluate_model(model, X_test, y_test) print("\\n" + "="*50) print("MODEL EVALUATION RESULTS") print("="*50) print(f"Mean Absolute Error (MAE): {mae:.4f}") print(f"Root Mean Squared Error (RMSE): {rmse:.4f}") print(f"R-squared (R²): {r2:.4f}") print(f"Samples evaluated: {len(y_test)}") print("="*50 + "\\n") # Generate sample recommendations print("[INFO] Generating sample recommendations...") recommendations = generate_sample_recommendations(model, X_test, ids_test, n=3) print("\\nSAMPLE RECOMMENDATIONS:") for rec in recommendations: print(f"\\nBase Recipe ID: {rec['base_recipe_id']}") print(f" Predicted Rating: {rec['predicted_rating']:.4f}") print(" Similar Recipes:") for sim_id, sim_rating in rec['similar_recipes']: print(f" - Recipe {sim_id}: {sim_rating:.4f}") if __name__ == "__main__": main()